import csv, math, numpy as np
from collections import Counter
from scipy.optimize import minimize
rows=list(csv.DictReader(open('/scr/wurgaft/auto-psych/agent_trees/d82b8b9c1e886668/repo/_runs/cell_1/experiment1/model_loop/responses.csv')))
def isprime(n): return n>1 and all(n%d for d in range(2,int(n**.5)+1))
R=range(1,101)
CATS={}
for k in range(3,13): CATS[f'mult{k}']={x for x in R if x%k==0}
CATS['sq']={x*x for x in range(1,11)}; CATS['cube']={x**3 for x in range(1,5)}
for b in [2,3,4,5,10]: CATS[f'pow{b}']={b**i for i in range(0,8) if b**i<=100}
CATS['prime']={x for x in R if isprime(x)}
W={c:math.log(100/len(s))/math.log(100) for c,s in CATS.items()}
def feats(ns,t,mode):
    ex=[int(x) for x in ns.split(',')]; t=int(t); n=len(ex)
    d=np.zeros(4);u=np.zeros(4);p=np.zeros(4);pr=np.zeros(4)
    for k,e in enumerate(ex[:4]):
        d[k]=abs(t-e)/10;u[k]=t%10!=e%10;p[k]=t%2!=e%2;pr[k]=1
    sp=(max(ex)-min(ex))/100 if n>1 else .5
    hg=(max(Counter(e%10 for e in ex).values())-1)/(n-1) if n>1 else .5
    shared=[c for c,s in CATS.items() if all(e in s for e in ex)] if n>1 else []
    miss=[W[c] for c in shared if t not in CATS[c]]
    hit=[W[c] for c in shared if t in CATS[c]]
    if mode==0: rm=max(miss,default=0)
    elif mode==1: rm=sum(miss)
    elif mode==2: rm=float(len(miss)>0)
    elif mode==3: rm=max(miss,default=0)-max(hit,default=0)
    return d,u,p,pr,sp,hg,rm
y=np.array([int(r['rating']) for r in rows])
def run(mode,use):
    F=[feats(r['number_set'],r['target'],mode) for r in rows]
    D,U,P,PR=[np.array([f[i] for f in F]) for i in range(4)]
    SP,HG,RM=[np.array([f[i] for f in F]) for i in range(4,7)]
    def nll(th):
        lm,lu,lp,st,ht,a,lb,cr=th
        ls=-np.exp(lm-st*SP)[:,None]*D-np.exp(lu+ht*HG)[:,None]*U-np.exp(lp)*P
        ls=np.where(PR>0,ls,-1e3); m=ls.max(1); L=m+np.log(np.exp(ls-m[:,None]).sum(1))
        z=a+np.exp(lb)*L-(cr*RM if use else 0)
        pp=np.clip(1/(1+np.exp(-z)),1e-6,1-1e-6)
        return -(y*np.log(pp)+(1-y)*np.log(1-pp)).sum()
    best=None
    for s in range(4):
        r=minimize(nll,np.random.RandomState(s).normal(0,.5,8),method='Nelder-Mead',options={'maxiter':20000,'maxfev':20000,'xatol':1e-5,'fatol':1e-5})
        r=minimize(nll,r.x,method='BFGS')
        if best is None or r.fun<best.fun: best=r
    return best
b=run(0,False); print('base',b.fun)
for m in range(4):
    r=run(m,True); print(m,r.fun,r.x.round(2))
