import csv, math, numpy as np
from collections import Counter
from scipy.optimize import minimize
rows=list(csv.DictReader(open('../../../../responses.csv')))
def isprime(n): return n>1 and all(n%d for d in range(2,int(n**.5)+1))
R=range(1,101)
CATS={}
for k in range(3,13): CATS[f'mult{k}']={x for x in R if x%k==0}
CATS['sq']={x*x for x in range(1,11)}; CATS['cube']={x**3 for x in range(1,5)}
for b in [2,3,4,5,10]: CATS[f'pow{b}']={b**i for i in range(1,8) if b**i<=100}
CATS['prime']={x for x in R if isprime(x)}
W={c:math.log(100/len(s)) for c,s in CATS.items()}
y=np.array([int(r['rating']) for r in rows])
def feats(ns,t,mode):
    ex=[int(x) for x in ns.split(',')]; t=int(t); n=len(ex)
    d=np.zeros(4);u=np.zeros(4);p=np.zeros(4);pr=np.zeros(4);q=np.zeros(4)
    for k,e in enumerate(ex[:4]):
        d[k]=abs(t-e)/10;u[k]=t%10!=e%10;p[k]=t%2!=e%2;pr[k]=1
        if mode=='sym': q[k]=sum(W[c] for c,s in CATS.items() if (t in s)!=(e in s))
        elif mode=='exhas': q[k]=sum(W[c] for c,s in CATS.items() if e in s and t not in s)
        elif mode=='exhas_max': q[k]=max([W[c] for c,s in CATS.items() if e in s and t not in s],default=0)
        elif mode=='common': q[k]=-sum(W[c] for c,s in CATS.items() if e in s and t in s)
        elif mode=='common_max': q[k]=-max([W[c] for c,s in CATS.items() if e in s and t in s],default=0)
    sp=(max(ex)-min(ex))/100 if n>1 else .5
    hg=(max(Counter(e%10 for e in ex).values())-1)/(n-1) if n>1 else .5
    return d,u,p,pr,q,sp,hg
def run(mode):
    F=[feats(r['number_set'],r['target'],mode) for r in rows]
    D,U,P,PR,Q=[np.array([f[i] for f in F]) for i in range(5)]
    SP,HG=[np.array([f[i] for f in F]) for i in range(5,7)]
    def nll(th):
        lm,lu,lp,st,ht,a,lb,cr=th
        ls=-np.exp(lm-st*SP)[:,None]*D-np.exp(lu+ht*HG)[:,None]*U-np.exp(lp)*P-cr*Q
        ls=np.where(PR>0,ls,-1e3); m=ls.max(1); L=m+np.log(np.exp(ls-m[:,None]).sum(1))
        z=np.clip(a+np.exp(lb)*L,-30,30)
        pp=np.clip(1/(1+np.exp(-z)),1e-6,1-1e-6)
        return -(y*np.log(pp)+(1-y)*np.log(1-pp)).sum()
    best=None
    for s in range(5):
        x0=np.random.RandomState(s).normal(0,.5,8); x0[7]=0.0 if mode=='none' else 0.3
        f=(lambda th: nll(np.r_[th[:7],0.0])) if mode=='none' else nll
        r=minimize(f,x0[:7] if mode=='none' else x0,method='Nelder-Mead',options={'maxiter':30000,'maxfev':30000,'xatol':1e-6,'fatol':1e-6})
        r=minimize(f,r.x,method='BFGS')
        if best is None or r.fun<best.fun: best=r
    return best
for m in ['none','sym','exhas','exhas_max','common','common_max']:
    r=run(m); print(m,round(r.fun,2),r.x.round(2),flush=True)
