    for k in range(3,13): C[f'mult{k}']={x for x in R if x%k==0}
    C['sq']={x*x for x in range(1,11)}; C['cube']={x**3 for x in range(1,5)}
    for b in [2,3,4,5,10]: C[f'pow{b}']={b**i for i in range(1,8) if b**i<=100}
    C['prime']={x for x in R if isprime(x)}
    for dd in range(10): C[f'end{dd}']={x for x in R if x%10==dd}
    C['even']={x for x in R if x%2==0}; C['odd']={x for x in R if x%2}
    if 'dec' in extra:
        for dd in range(10): C[f'dec{dd}']={x for x in R if (x-1)//10==dd}
    if 'contain' in extra:
        for dd in range(10): C[f'has{dd}']={x for x in R if str(dd) in str(x)}
    return C
y=np.array([int(r['rating']) for r in rows])
def rulefeat(ns,t,C,W,mode,minn):
    ex=[int(x) for x in ns.split(',')]; t=int(t)
    if len(ex)<minn: return 0.0
    sh=[c for c in C if all(e in C[c] for e in ex)]
    miss=max([W[c] for c in sh if t not in C[c]],default=0); hit=max([W[c] for c in sh if t in C[c]],default=0)
    if mode=='diff': return hit-miss
    if mode=='hit': return hit
    if mode=='miss': return -miss
