import csv, math, numpy as np
from collections import Counter
from scipy.optimize import minimize
rows=list(csv.DictReader(open('../../../../responses.csv')))
def isprime(n): return n>1 and all(n%d for d in range(2,int(n**.5)+1))
R=range(1,101)
def mkcats(extra):
    C={}
    for k in range(3,13): C[f'mult{k}']={x for x in R if x%k==0}
    C['sq']={x*x for x in range(1,11)}; C['cube']={x**3 for x in range(1,5)}
    for b in [2,3,4,5,10]: C[f'pow{b}']={b**i for i in range(1,8) if b**i<=100}
    C['prime']={x for x in R if isprime(x)}
    for dd in range(10): C[f'end{dd}']={x for x in R if x%10==dd}
    C['even']={x for x in R if x%2==0}; C['odd']={x for x in R if x%2}
    if 'dec' in extra:
        for dd in range(10): C[f'dec{dd}']={x for x in R if (x-1)//10==dd}
    if 'contain' in extra:
        for dd in range(10): C[f'has{dd}']={x for x in R if str(dd) in str(x)}
    return C
y=np.array([int(r['rating']) for r in rows])
def rulefeat(ns,t,C,W,mode,minn):
    ex=[int(x) for x in ns.split(',')]; t=int(t)
    if len(ex)<minn: return 0.0
    sh=[c for c in C if all(e in C[c] for e in ex)]
    miss=max([W[c] for c in sh if t not in C[c]],default=0); hit=max([W[c] for c in sh if t in C[c]],default=0)
    if mode=='diff': return hit-miss
    if mode=='hit': return hit
    if mode=='miss': return -miss
    if mode=='best': # does target satisfy the single most specific shared rule
        if not sh: return 0.0
        b=max(sh,key=lambda c:W[c]); return W[b] if t in C[b] else -W[b]
def base(ns,t):
    ex=[int(x) for x in ns.split(',')]; t=int(t); n=len(ex)
    d=np.zeros(4);u=np.zeros(4);p=np.zeros(4);pr=np.zeros(4)
    for k,e in enumerate(ex[:4]):
        d[k]=abs(t-e)/10;u[k]=t%10!=e%10;p[k]=t%2!=e%2;pr[k]=1
    sp=(max(ex)-min(ex))/100 if n>1 else .5
    hg=(max(Counter(e%10 for e in ex).values())-1)/(n-1) if n>1 else .5
    return d,u,p,pr,sp,hg
B=[base(r['number_set'],r['target']) for r in rows]
D,U,P,PR=[np.array([f[i] for f in B]) for i in range(4)]
SP,HG=[np.array([f[i] for f in B]) for i in range(4,6)]
def run(RM):
    def nll(th):
        lm,lu,lp,st,ht,a,lb,cr=th
        ls=-np.exp(lm-st*SP)[:,None]*D-np.exp(lu+ht*HG)[:,None]*U-np.exp(lp)*P
        ls=np.where(PR>0,ls,-1e3); m=ls.max(1); L=m+np.log(np.exp(ls-m[:,None]).sum(1))
        z=np.clip(a+np.exp(lb)*L+cr*RM,-30,30)
        pp=np.clip(1/(1+np.exp(-z)),1e-6,1-1e-6)
        return -(y*np.log(pp)+(1-y)*np.log(1-pp)).sum()
    best=None
    for s in range(3):
        x0=np.random.RandomState(s).normal(0,.5,8)
        r=minimize(nll,x0,method='Nelder-Mead',options={'maxiter':30000,'maxfev':30000,'xatol':1e-6,'fatol':1e-6})
        r=minimize(nll,r.x,method='BFGS')
        if best is None or r.fun<best.fun: best=r
    return best
for extra in [(),('dec',),('contain',)]:
    C=mkcats(extra)
    for wt in ['log','inv']:
        W={c:(math.log(100/len(s)) if wt=='log' else 10/len(s)) for c,s in C.items()}
        for mode in ['diff','hit','miss','best']:
            for minn in [1,2]:
                RM=np.array([rulefeat(r['number_set'],r['target'],C,W,mode,minn) for r in rows])
                r=run(RM); print(extra,wt,mode,minn,round(r.fun,2),round(r.x[7],2),flush=True)
